parameters.jsonBody:
={
  "messaging_product": "whatsapp",
  "recipient_type": "individual",
  "to": "{{ $json.phone }}",
  "type": "interactive",
  "interactive": {
    "type": "button",
    "header": { "type": "text", "text": "🏛️ Khaki Tours: Tour Opportunity" },
    "body": {
      "text": "Hello! New assignment opportunity:\n\n• *Tour:* {{ $('Khaki OS Dispatch Trigger').item.json.body.tour_title }}\n• *Slot:* {{ $('Khaki OS Dispatch Trigger').item.json.body.departure_date }}\n• *Pax:* {{ $('Khaki OS Dispatch Trigger').item.json.body.group_size }} Guests\n• *Payout:* ₹{{ $('Khaki OS Dispatch Trigger').item.json.body.payout_amount_inr }}\n\n*Zero-portal interaction: Simply tap your response below within 30 minutes.*"
    },
    "footer": { "text": "Khaki Operations Hub | Zero-Login Ambassador Network" },
    "action": {
      "buttons": [
        {
          "type": "reply",
          "reply": {
            "id": "DISPATCH_ACCEPT_{{ $('Khaki OS Dispatch Trigger').item.json.body.dispatch_id }}",
            "title": "✅ Accept Tour"
          }
        },
        {
          "type": "reply",
          "reply": {
            "id": "DISPATCH_DECLINE_{{ $('Khaki OS Dispatch Trigger').item.json.body.dispatch_id }}",
            "title": "❌ Busy / Pass"
          }
        }
      ]
    }
  }
}

={
  "messaging_product": "whatsapp",
  "to": "{{ $env.PRIYA_OPS_PHONE }}",
  "type": "text",
  "text": {
    "body": "🚨 *KHAKI OPS ESCALATION ALERT*\n\nTour: {{ $('Khaki OS Dispatch Trigger').item.json.body.tour_title }}\nDate: {{ $('Khaki OS Dispatch Trigger').item.json.body.departure_date }}\n\n⚠️ *Zero guide responses after 30-minute broadcast.*\nPlease manually assign or call reserve ambassadors from the Khaki Travel OS dispatch board:\n👉 {{ $env.KHAKI_OS_APP_URL }}/dispatch"
  }
}
